"""Manage peer records in a gateway generated by provision.py (Linux)."""
import argparse
import base64
import binascii
import fcntl
import os
from pathlib import Path
import re
import subprocess
import tempfile

NAME = r"[a-z0-9][a-z0-9-]{0,31}"
PEER = re.compile(r"# (" + NAME + r")\n\[Peer\]\nPublicKey = (\S+)\nAllowedIPs = 10\.77\.0\.(\d+)/32")


def change(config, action, name=None, key=None):
    parts = config.strip().split("\n\n")
    header = parts[0]
    if not header.startswith("[Interface]\nAddress = 10.77.0.1/24\n") or "[Peer]" in header:
        raise ValueError("Expected a gateway generated by provision.py")
    peers = {}
    addresses = set()
    keys = set()
    for block in parts[1:]:
        match = PEER.fullmatch(block)
        if not match:
            raise ValueError("Unknown peer format; preserving the existing config")
        label, public, host = match.groups()
        host = int(host)
        if label in peers or public in keys or host in addresses or not 2 <= host <= 254:
            raise ValueError("Conflicting peer records")
        peers[label] = (public, host)
        keys.add(public)
        addresses.add(host)
    if action == "add":
        if not re.fullmatch(NAME, name):
            raise ValueError("Invalid device name")
        try:
            raw = base64.b64decode(key, validate=True)
        except (ValueError, binascii.Error):
            raise ValueError("Invalid WireGuard public key") from None
        if len(raw) != 32 or not any(raw) or base64.b64encode(raw).decode() != key:
            raise ValueError("Invalid WireGuard public key")
        if name in peers:
            if peers[name][0] != key:
                raise ValueError("Device name already has a different key")
        elif key in keys:
            raise ValueError("Public key already enrolled under another name")
        else:
            host = next((n for n in range(2, 255) if n not in addresses), None)
            if host is None:
                raise ValueError("Gateway address pool is full")
            peers[name] = (key, host)
    elif action == "remove":
        peers.pop(name, None)
    blocks = [header]
    for label, (public, host) in peers.items():
        blocks.append(f"# {label}\n[Peer]\nPublicKey = {public}\nAllowedIPs = 10.77.0.{host}/32")
    return "\n\n".join(blocks) + "\n", peers


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("config", type=Path)
    parser.add_argument("--offline", action="store_true", help="edit a staged configuration only")
    commands = parser.add_subparsers(dest="action", required=True)
    commands.add_parser("list")
    add = commands.add_parser("add")
    add.add_argument("name")
    add.add_argument("public_key")
    commands.add_parser("remove").add_argument("name")
    args = parser.parse_args()
    path = args.config.resolve(strict=True)
    live = path.parent == Path("/etc/wireguard")
    if args.action != "list" and live == args.offline:
        parser.error("Use live mode under /etc/wireguard and --offline for a staged config")
    if not re.fullmatch(r"wg-[a-z][a-z0-9]{0,9}\.conf", path.name):
        parser.error("Expected wg-REGION.conf")
    with path.with_suffix(".lock").open("a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        original = path.read_text()
        updated, peers = change(original, args.action, getattr(args, "name", None),
                                getattr(args, "public_key", None))
        if args.action != "list":
            if updated != original:
                with tempfile.NamedTemporaryFile(dir=path.parent, mode="w", delete=False) as tmp:
                    try:
                        tmp.write(updated)
                        tmp.flush()
                        os.fsync(tmp.fileno())
                        os.replace(tmp.name, path)
                    finally:
                        Path(tmp.name).unlink(missing_ok=True)
            if live:
                subprocess.run(["systemctl", "reload", "wg-quick@" + path.stem], check=True)
        for label, (_, host) in peers.items():
            print(f"{label}\t10.77.0.{host}/32")


if __name__ == "__main__":
    try:
        main()
    except subprocess.CalledProcessError:
        raise SystemExit("Config saved. Live reload failed. Check the service and repeat the command.")
    except (ValueError, OSError) as error:
        raise SystemExit(str(error))
